#[cfg(feature = "viewer")]
use re_viewer::external::egui;

#[cfg(feature = "viewer")]
use super::key_mapper::extract_terminal_input_bytes;
#[cfg(feature = "viewer")]
use super::session::TerminalSession;

/// Result of rendering the interactive terminal widget in a frame.
#[cfg(feature = "viewer")]
#[derive(Default)]
pub struct TerminalWidgetOutput {
    /// Bytes generated by user keyboard/paste input to be sent to the PTY.
    pub input_bytes: Vec<u8>,
    /// Optional `(cols, rows)` if the terminal viewport was resized this frame.
    pub resized: Option<(u16, u16)>,
}

#[cfg(feature = "viewer")]
const DEFAULT_BG: egui::Color32 = egui::Color32::from_rgb(13, 15, 18);
#[cfg(feature = "viewer")]
const DEFAULT_FG: egui::Color32 = egui::Color32::from_rgb(212, 218, 226);

/// Converts a `vt100::Color` into an `egui::Color32`.
#[cfg(feature = "viewer")]
pub fn vt100_color_to_egui(color: vt100::Color, is_fg: bool, bold: bool) -> egui::Color32 {
    match color {
        vt100::Color::Default => {
            if is_fg {
                if bold {
                    egui::Color32::from_rgb(245, 248, 252)
                } else {
                    DEFAULT_FG
                }
            } else {
                DEFAULT_BG
            }
        }
        vt100::Color::Idx(idx) => {
            // If bold is active and color is standard 0..7, promote to bright 8..15 for foreground
            let effective_idx = if is_fg && bold && idx < 8 {
                idx + 8
            } else {
                idx
            };
            ansi_idx_to_rgb(effective_idx)
        }
        vt100::Color::Rgb(r, g, b) => egui::Color32::from_rgb(r, g, b),
    }
}

/// Maps an 8-bit ANSI color index (`0..=255`) to `egui::Color32`.
#[cfg(feature = "viewer")]
fn ansi_idx_to_rgb(idx: u8) -> egui::Color32 {
    match idx {
        // Standard 16 colors (modern dark theme palette)
        0 => egui::Color32::from_rgb(30, 34, 42), // Black
        1 => egui::Color32::from_rgb(224, 108, 117), // Red
        2 => egui::Color32::from_rgb(152, 195, 121), // Green
        3 => egui::Color32::from_rgb(229, 192, 123), // Yellow
        4 => egui::Color32::from_rgb(97, 175, 239), // Blue
        5 => egui::Color32::from_rgb(198, 120, 221), // Magenta
        6 => egui::Color32::from_rgb(86, 182, 194), // Cyan
        7 => egui::Color32::from_rgb(171, 178, 191), // White (light gray)
        // Bright 8..15
        8 => egui::Color32::from_rgb(92, 99, 112), // Bright Black (gray)
        9 => egui::Color32::from_rgb(244, 135, 113), // Bright Red
        10 => egui::Color32::from_rgb(181, 232, 144), // Bright Green
        11 => egui::Color32::from_rgb(240, 214, 145), // Bright Yellow
        12 => egui::Color32::from_rgb(130, 196, 248), // Bright Blue
        13 => egui::Color32::from_rgb(218, 152, 238), // Bright Magenta
        14 => egui::Color32::from_rgb(120, 214, 224), // Bright Cyan
        15 => egui::Color32::from_rgb(255, 255, 255), // Bright White
        // 6x6x6 Color Cube (16..=231)
        16..=231 => {
            let n = idx - 16;
            let r_idx = n / 36;
            let g_idx = (n % 36) / 6;
            let b_idx = n % 6;
            let to_val = |c: u8| if c == 0 { 0 } else { 55 + c * 40 };
            egui::Color32::from_rgb(to_val(r_idx), to_val(g_idx), to_val(b_idx))
        }
        // Grayscale ramp (232..=255)
        232..=255 => {
            let gray = 8 + (idx - 232) * 10;
            egui::Color32::from_rgb(gray, gray, gray)
        }
    }
}

/// Notifica o ambiente Web (JavaScript) sobre o estado de foco do terminal.
/// Quando focado, o listener no `window` do navegador intercepta e previne ações padrão
/// como recarregar página (Ctrl+R / F5), abrir busca (Ctrl+F), scroll de setas/Home/End, etc.
#[cfg(target_arch = "wasm32")]
pub fn set_terminal_focus_web(focused: bool) {
    if let Some(window) = web_sys::window() {
        let _ = js_sys::Reflect::set(
            &window,
            &wasm_bindgen::JsValue::from_str("__perse_terminal_focused"),
            &wasm_bindgen::JsValue::from_bool(focused),
        );
    }
}

#[cfg(not(target_arch = "wasm32"))]
pub fn set_terminal_focus_web(_focused: bool) {}

/// Renders an interactive VT100 terminal screen inside `ui`.
#[cfg(feature = "viewer")]
pub fn show_terminal_widget(
    ui: &mut egui::Ui,
    session: &mut TerminalSession,
) -> TerminalWidgetOutput {
    let mut output = TerminalWidgetOutput::default();

    let font_id = egui::FontId::monospace(13.0);

    // Measure single monospace character cell dimensions
    let (char_width, char_height) = ui.fonts_mut(|f| {
        let w = f.glyph_width(&font_id, 'M').max(6.0);
        let h = f.row_height(&font_id).max(12.0);
        (w, h)
    });

    let available = ui.available_size();
    let pad_x = 6.0;
    let pad_y = 6.0;

    let inner_w = (available.x - pad_x * 2.0).max(char_width * 10.0);
    let inner_h = (available.y - pad_y * 2.0).max(char_height * 2.0);

    let new_cols = (inner_w / char_width).floor() as u16;
    let new_rows = (inner_h / char_height).floor() as u16;

    if session.resize(new_cols, new_rows) {
        output.resized = Some((session.cols, session.rows));
    }

    let widget_id = ui.make_persistent_id(("vt100_terminal_viewport", &session.id));
    let (rect, _auto_response) = ui.allocate_exact_size(available, egui::Sense::hover());
    let response = ui.interact(rect, widget_id, egui::Sense::click_and_drag());

    // Gerenciamento de foco do terminal:
    if response.clicked() || response.drag_started() {
        session.is_focused = true;
        response.request_focus();
    } else if ui.input(|i| i.pointer.any_pressed()) && !response.hovered() {
        // Se o usuário clicou em qualquer outra área fora do terminal, perde o foco
        session.is_focused = false;
        session.clear_selection();
    }

    if session.is_focused {
        ui.memory_mut(|mem| {
            mem.request_focus(widget_id);
            mem.set_focus_lock_filter(
                widget_id,
                egui::EventFilter {
                    tab: true,
                    horizontal_arrows: true,
                    vertical_arrows: true,
                    escape: true,
                },
            );
        });

        // Informa o Rerun e o egui que um widget de edição de texto está em foco.
        // Sem isso, os atalhos de timeline do Rerun (ArrowLeft, ArrowRight, ArrowUp, ArrowDown,
        // Home, End, Space) consomem e removem esses eventos da fila antes que o terminal possa processá-los.
        egui::text_edit::TextEditState::default().store(ui.ctx(), widget_id);
    } else {
        ui.ctx().data_mut(|d| {
            d.remove::<egui::text_edit::TextEditState>(widget_id);
        });
    }

    let has_focus = session.is_focused;
    set_terminal_focus_web(has_focus);

    // Handle mouse wheel scrolling when hovered
    if response.hovered() {
        let scroll_delta = ui.input(|i| i.smooth_scroll_delta.y);
        if scroll_delta.abs() > 0.5 {
            // Positive scroll_delta.y means scrolling up into history
            let lines = (scroll_delta / char_height).round() as isize;
            if lines != 0 {
                session.scroll(lines);
            }
        }
    }

    let origin = rect.min + egui::vec2(pad_x, pad_y);
    let (rows, cols) = session.parser.screen().size();
    let app_cursor = session.parser.screen().application_cursor();

    // Ativa o IME e posiciona o text agent invisível no cursor do terminal quando em foco.
    // Isso é essencial no ambiente Web para que o navegador execute a composição nativa
    // de teclas mortas (acentos como ~, ^, ´, ` gerando ã, é, etc.) e caracteres CJK.
    if session.is_focused {
        let (cur_row, cur_col) = session.parser.screen().cursor_position();
        let cx = origin.x + f32::from(cur_col) * char_width;
        let cy = origin.y + f32::from(cur_row) * char_height;
        let cursor_rect =
            egui::Rect::from_min_size(egui::pos2(cx, cy), egui::vec2(char_width, char_height));
        let to_global = ui
            .ctx()
            .layer_transform_to_global(ui.layer_id())
            .unwrap_or_default();

        ui.output_mut(|o| {
            o.ime = Some(egui::output::IMEOutput {
                purpose: egui::IMEPurpose::Normal,
                rect: to_global * rect,
                cursor_rect: to_global * cursor_rect,
                should_interrupt_composition: false,
            });
        });
    }

    // Seleção de texto com o botão primário do mouse (arrastar para selecionar)
    if response.drag_started_by(egui::PointerButton::Primary) {
        if let Some(pos) = response.interact_pointer_pos() {
            let col = (((pos.x - origin.x) / char_width).floor() as isize)
                .clamp(0, cols.saturating_sub(1) as isize) as usize;
            let row = (((pos.y - origin.y) / char_height).floor() as isize)
                .clamp(0, rows.saturating_sub(1) as isize) as usize;
            session.selection = Some(super::session::TerminalSelection {
                start: (row, col),
                end: (row, col),
            });
        }
    } else if response.dragged_by(egui::PointerButton::Primary) {
        if let Some(pos) = response.interact_pointer_pos() {
            let col = (((pos.x - origin.x) / char_width).floor() as isize)
                .clamp(0, cols.saturating_sub(1) as isize) as usize;
            let row = (((pos.y - origin.y) / char_height).floor() as isize)
                .clamp(0, rows.saturating_sub(1) as isize) as usize;
            if let Some(ref mut sel) = session.selection {
                sel.end = (row, col);
            }
        }
    } else if response.clicked_by(egui::PointerButton::Primary) {
        session.clear_selection();
    }

    // Capture keyboard input when focused
    if has_focus {
        let has_sel = session.selection.is_some();
        let mut copy_requested = false;

        let bytes = ui.input(|i| {
            // Se houver seleção e o usuário pressionar Ctrl+C (ou Cmd+C) ou disparar Event::Copy, copiamos o texto
            if has_sel {
                let is_copy = i.events.iter().any(|e| {
                    if let egui::Event::Key {
                        key: egui::Key::C,
                        pressed: true,
                        modifiers,
                        ..
                    } = e
                    {
                        (modifiers.ctrl || modifiers.command || modifiers.mac_cmd) && !modifiers.alt
                    } else {
                        matches!(e, egui::Event::Copy)
                    }
                });
                if is_copy {
                    copy_requested = true;
                }
            }

            extract_terminal_input_bytes(&i.events, app_cursor, has_sel)
        });

        if copy_requested {
            let text = session.get_selected_text();
            if !text.is_empty() {
                ui.ctx().copy_text(text);
            }
            session.clear_selection();
        }

        if !bytes.is_empty() {
            // Automatically jump back to live bottom when the user types
            session.scroll_to_bottom();
            output.input_bytes = bytes;
        }
    }

    // Paint terminal background and border
    let painter = ui.painter_at(rect);
    painter.rect_filled(rect, 4.0, DEFAULT_BG);

    let border_color = if has_focus {
        egui::Color32::from_rgb(70, 130, 210)
    } else {
        egui::Color32::from_rgb(35, 39, 46)
    };
    painter.rect_stroke(
        rect,
        4.0,
        egui::Stroke::new(1.0, border_color),
        egui::StrokeKind::Inside,
    );

    let screen = session.parser.screen();
    let scrollback_offset = screen.scrollback();

    // Render cells row by row
    for row in 0..rows {
        let y = origin.y + f32::from(row) * char_height;
        if y + char_height > rect.max.y {
            break;
        }

        for col in 0..cols {
            let Some(cell) = screen.cell(row, col) else {
                continue;
            };

            if cell.is_wide_continuation() {
                continue;
            }

            let x = origin.x + f32::from(col) * char_width;
            let cell_w = if cell.is_wide() {
                char_width * 2.0
            } else {
                char_width
            };

            let cell_rect =
                egui::Rect::from_min_size(egui::pos2(x, y), egui::vec2(cell_w, char_height));

            let bold = cell.bold();
            let mut fg = vt100_color_to_egui(cell.fgcolor(), true, bold);
            let mut bg = vt100_color_to_egui(cell.bgcolor(), false, false);

            if cell.inverse() {
                std::mem::swap(&mut fg, &mut bg);
            }

            if cell.dim() {
                fg = egui::Color32::from_rgba_unmultiplied(fg.r(), fg.g(), fg.b(), 160);
            }

            let is_selected = session
                .selection
                .as_ref()
                .map_or(false, |s| s.contains(row as usize, col as usize));

            // Draw cell background if selected or non-default
            if is_selected {
                let sel_bg = egui::Color32::from_rgba_unmultiplied(65, 125, 225, 115);
                painter.rect_filled(cell_rect, 0.0, sel_bg);
            } else if bg != DEFAULT_BG {
                painter.rect_filled(cell_rect, 0.0, bg);
            }

            // Draw character glyph
            let text = cell.contents();
            if !text.is_empty() && text != " " {
                painter.text(
                    egui::pos2(x, y),
                    egui::Align2::LEFT_TOP,
                    text,
                    font_id.clone(),
                    fg,
                );
            }

            // Draw underline if set
            if cell.underline() {
                let line_y = y + char_height - 1.5;
                painter.line_segment(
                    [egui::pos2(x, line_y), egui::pos2(x + cell_w, line_y)],
                    egui::Stroke::new(1.0, fg),
                );
            }
        }
    }

    // Draw cursor when at bottom of scrollback and cursor is visible
    if scrollback_offset == 0 && !screen.hide_cursor() {
        let (cur_row, cur_col) = screen.cursor_position();
        if cur_row < rows && cur_col < cols {
            let cx = origin.x + f32::from(cur_col) * char_width;
            let cy = origin.y + f32::from(cur_row) * char_height;
            let cursor_rect =
                egui::Rect::from_min_size(egui::pos2(cx, cy), egui::vec2(char_width, char_height));

            if has_focus {
                painter.rect_filled(
                    cursor_rect,
                    1.0,
                    egui::Color32::from_rgba_unmultiplied(200, 210, 225, 180),
                );
                // Re-draw character under block cursor in dark color for contrast
                if let Some(cell) = screen.cell(cur_row, cur_col) {
                    let text = cell.contents();
                    if !text.is_empty() && text != " " {
                        painter.text(
                            egui::pos2(cx, cy),
                            egui::Align2::LEFT_TOP,
                            text,
                            font_id.clone(),
                            DEFAULT_BG,
                        );
                    }
                }
            } else {
                // Hollow cursor when unfocused
                painter.rect_stroke(
                    cursor_rect,
                    1.0,
                    egui::Stroke::new(1.0, egui::Color32::from_rgb(140, 150, 165)),
                    egui::StrokeKind::Inside,
                );
            }
        }
    }

    // Show a subtle scrollback badge if user scrolled up in history
    if scrollback_offset > 0 {
        let badge_text = format!(
            "↑ Scrollback: {} linhas (Role para baixo ou digite)",
            scrollback_offset
        );
        let badge_pos = egui::pos2(rect.max.x - 10.0, rect.min.y + 8.0);
        painter.text(
            badge_pos,
            egui::Align2::RIGHT_TOP,
            badge_text,
            egui::FontId::proportional(11.0),
            egui::Color32::from_rgb(229, 192, 123),
        );
    }

    output
}
